const input = $input.first().json || {};
const body = input.body || input;

const serviceName = (body.serviceName || '').toString().trim();
const serviceDescription = (body.serviceDescription || '').toString().trim();

const rawKeywords = Array.isArray(body.keywordsJa) ? body.keywordsJa : [];
const keywordsJa = rawKeywords.map((k) => String(k).trim()).filter(Boolean).slice(0, 10);

const rawCompetitors = Array.isArray(body.competitorNamesJa) ? body.competitorNamesJa : [];
const competitorNamesJa = rawCompetitors.map((k) => String(k).trim()).filter(Boolean).slice(0, 10);

if (!serviceName) {
  return [{ json: { validationError: true, errorMessage: 'serviceName is required but was empty or missing.' } }];
}
if (keywordsJa.length === 0) {
  return [{ json: { validationError: true, errorMessage: 'keywordsJa must be a non-empty array of Japanese keyword strings, e.g. ["\u7d4c\u8cbb\u7cbe\u7b97", "\u9818\u53ce\u66f8 OCR"].' } }];
}

return [{ json: { validationError: false, serviceName, serviceDescription, keywordsJa, competitorNamesJa } }];

const cfg = $('Validate request').first().json;
const feedItmedia = $('Fetch ITmedia Business feed').first().json;
const feedImpress = $('Fetch Impress Watch feed').first().json;
const feedPrtimes = $('Fetch PR TIMES feed').first().json;

function extractItems(raw, sourceName, cap) {
  const xmlText = raw && !raw.error ? raw.data : '';
  if (!xmlText || typeof xmlText !== 'string') return [];
  const blocks = xmlText.match(/<item[\s\S]*?<\/item>/gi) || [];
  const pick = (block, tag) => {
    const m = block.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i'));
    if (!m) return '';
    return m[1]
      .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
      .replace(/<[^>]+>/g, '')
      .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
      .trim();
  };
  return blocks.slice(0, cap).map((block) => ({
    source: sourceName,
    title: pick(block, 'title'),
    link: pick(block, 'link'),
    date: pick(block, 'pubDate') || pick(block, 'dc:date') || '',
    description: pick(block, 'description'),
  })).filter((it) => it.title);
}

const sourceStatus = [
  { name: 'ITmedia \u30d3\u30b8\u30cd\u30b9\u30aa\u30f3\u30e9\u30a4\u30f3', ok: !(feedItmedia && feedItmedia.error) },
  { name: 'Impress Watch', ok: !(feedImpress && feedImpress.error) },
  { name: 'PR TIMES', ok: !(feedPrtimes && feedPrtimes.error) },
];

const allItems = [
  ...extractItems(feedItmedia, 'ITmedia \u30d3\u30b8\u30cd\u30b9\u30aa\u30f3\u30e9\u30a4\u30f3', 30),
  ...extractItems(feedImpress, 'Impress Watch', 30),
  ...extractItems(feedPrtimes, 'PR TIMES', 60),
];

const needles = [...cfg.keywordsJa, ...cfg.competitorNamesJa].map((k) => k.toLowerCase());
const matches = allItems.filter((it) => {
  const haystack = `${it.title} ${it.description}`.toLowerCase();
  return needles.some((k) => haystack.includes(k));
});

matches.sort((a, b) => {
  const da = Date.parse(a.date);
  const db = Date.parse(b.date);
  if (Number.isNaN(da) && Number.isNaN(db)) return 0;
  if (Number.isNaN(da)) return 1;
  if (Number.isNaN(db)) return -1;
  return db - da;
});

const cappedMatches = matches.slice(0, 15);

return [{
  json: {
    serviceName: cfg.serviceName,
    serviceDescription: cfg.serviceDescription,
    keywords: [...cfg.keywordsJa, ...cfg.competitorNamesJa],
    sourcesChecked: ['ITmedia \u30d3\u30b8\u30cd\u30b9\u30aa\u30f3\u30e9\u30a4\u30f3', 'Impress Watch', 'PR TIMES'],
    sourceStatus,
    totalArticlesScanned: allItems.length,
    matches: cappedMatches,
    matchCount: cappedMatches.length,
  },
}];

const d = $input.first().json;
const failedSources = (d.sourceStatus || []).filter((s) => !s.ok).map((s) => s.name);
const matchesFound = d.matchCount > 0;

let message;
if (matchesFound) {
  const preview = d.matches.slice(0, 5).map((m, i) => `${i + 1}. [${m.source}] ${m.title}${m.date ? ' (' + m.date + ')' : ''}\n${m.link}`).join('\n');
  const more = d.matchCount > 5 ? `\n...\u307b\u304b${d.matchCount - 5}\u4ef6` : '';
  message = `\u300c${d.serviceName}\u300d\u306b\u95a2\u9023\u3059\u308b\u30ad\u30fc\u30ef\u30fc\u30c9\uff08${d.keywords.join('\u3001')}\uff09\u306b\u3064\u3044\u3066\u3001\u78ba\u8a8d\u3057\u305f\u7bc4\u56f2\uff08${d.sourcesChecked.join('\u3001')}\u3001\u8a18\u4e8b${d.totalArticlesScanned}\u4ef6\uff09\u3067${d.matchCount}\u4ef6\u306e\u95a2\u9023\u8a18\u4e8b\u304c\u898b\u3064\u304b\u308a\u307e\u3057\u305f\u3002\n\n${preview}${more}\n\n\u3053\u308c\u306f\u8a71\u984c\u5316\u306e\u6709\u7121\u3092\u793a\u3059\u4e00\u6b21\u60c5\u5831\u3067\u3042\u308a\u3001AI\u306b\u3088\u308b\u89e3\u91c8\u306f\u542b\u307e\u308c\u3066\u3044\u307e\u305b\u3093\u3002\u5185\u5bb9\u306f\u5404\u30ea\u30f3\u30af\u5148\u3067\u76f4\u63a5\u3054\u78ba\u8a8d\u306e\u3046\u3048\u3001\u9700\u8981\u306e\u5b9f\u614b\u306f\u6b63\u5f0f\u306a\u5e02\u5834\u8abf\u67fb\u3067\u78ba\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002`;
} else {
  message = `\u300c${d.serviceName}\u300d\u306b\u95a2\u9023\u3059\u308b\u30ad\u30fc\u30ef\u30fc\u30c9\uff08${d.keywords.join('\u3001')}\uff09\u306b\u3064\u3044\u3066\u3001\u4eca\u56de\u78ba\u8a8d\u3057\u305f\u7bc4\u56f2\uff08${d.sourcesChecked.join('\u3001')}\u3001\u8a18\u4e8b${d.totalArticlesScanned}\u4ef6\uff09\u3067\u306f\u3001\u8a71\u984c\u5316\u3092\u793a\u3059\u8a18\u4e8b\u3092\u78ba\u8a8d\u3067\u304d\u307e\u305b\u3093\u3067\u3057\u305f\u3002\n\n\u3053\u308c\u306f\u65e5\u672c\u5e02\u5834\u306b\u9700\u8981\u304c\u7121\u3044\u3053\u3068\u3092\u610f\u5473\u3059\u308b\u3082\u306e\u3067\u306f\u306a\u304f\u3001\u78ba\u8a8d\u3057\u305f\u60c5\u5831\u6e90\u30fb\u671f\u9593\u30fb\u30ad\u30fc\u30ef\u30fc\u30c9\u306e\u7bc4\u56f2\u5185\u3067\u306e\u7d50\u679c\u3067\u3059\u3002\u30ad\u30fc\u30ef\u30fc\u30c9\u3092\u5e83\u3052\u308b\u3001\u78ba\u8a8d\u671f\u9593\u3092\u5ef6\u3070\u3059\u3001\u4ed6\u306e\u60c5\u5831\u6e90\uff08\u696d\u754c\u5c02\u9580\u30e1\u30c7\u30a3\u30a2\u30fb SNS\u30fb\u5c55\u793a\u4f1a\u60c5\u5831\u7b49\uff09\u3082\u78ba\u8a8d\u3059\u308b\u3053\u3068\u3092\u63a8\u5968\u3057\u307e\u3059\u3002`;
}
if (failedSources.length > 0) {
  message += `\n\n\u6ce8\u610f\uff1a\u4ee5\u4e0b\u306e\u60c5\u5831\u6e90\u306f\u53d6\u5f97\u306b\u5931\u6557\u3057\u305f\u305f\u3081\u3001\u3053\u306e\u7d50\u679c\u306b\u306f\u53cd\u6620\u3055\u308c\u3066\u3044\u307e\u305b\u3093: ${failedSources.join('\u3001')}`;
}

return [{
  json: {
    success: true,
    matchesFound,
    serviceName: d.serviceName,
    sourcesChecked: d.sourcesChecked,
    totalArticlesScanned: d.totalArticlesScanned,
    matchCount: d.matchCount,
    matches: d.matches,
    message,
  },
}];

const generated = $('Build response').first().json;
const config = $input.first().json;

const preview = (generated.message || '').slice(0, 500);

return [{
  json: {
    slackWebhookUrl: config.slackWebhookUrl,
    slackRequestBody: { text: `:mag: Japan demand-signal scan \u2014 ${generated.serviceName} (${generated.matchCount} \u8a18\u4e8b\u4e00\u81f4):\n${preview}` }
  }
}];
